@GameTestHolder(HeavenlyRestriction.ID) @PrefixGameTestTemplate(false)
public final class LoanSharkGameTests {
    static ServerPlayer actor(GameTestHelper h){var at=h.absolutePos(net.minecraft.core.BlockPos.ZERO).offset(1,4,1);var p=net.neoforged.neoforge.common.util.FakePlayerFactory.get(h.getLevel(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"LoanTest"));p.setPos(at.getX(),at.getY(),at.getZ());p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);io.github.manasmods.manascore.race.api.RaceAPI.getRaceFrom(p).setRace(io.github.manasmods.tensura.registry.race.TensuraRaces.HUMAN.get(),false);EnergyHelper.setBaseMaxEP(p,20000000);TensuraStorages.getExistenceFrom(p).setAura(1000000);TensuraStorages.getExistenceFrom(p).setMagicule(1000000);return p;}
    static ServerPlayer lender(GameTestHelper h){var p=actor(h);RestrictionData.learnReward(p,HeavenlyRestriction.LOAN_SHARK.get());RestrictionData.learnReward(p,HeavenlyRestriction.SCHEMA.get());SkillAPI.getSkillsFrom(p).getSkill(HeavenlyRestriction.SCHEMA.get()).orElseThrow(()->new IllegalStateException("Lender Schema grant failed")).setMastery(888);return p;}
    static LivingEntity subordinate(GameTestHelper h,ServerPlayer p){var e=target(h,p.position().add(3,0,0));TensuraStorages.getExistenceFrom(e).setPermanentOwner(p.getUUID());EnergyHelper.setBaseMaxEP(e,100000);return e;}
    static ManasSkillInstance gift(LivingEntity p){return SkillAPI.getSkillsFrom(p).getSkill(HeavenlyRestriction.SCHEMA.get()).orElseThrow();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void copiesMasteryButNeverStoredBanksOrPreexistingSkills(GameTestHelper h){var p=lender(h);var e=subordinate(h,p);gift(p).getOrCreateTag().putInt("private_inventory",42);gift(p).getOrCreateTag().put("schema.build",new net.minecraft.nbt.CompoundTag());var l=LoanShark.lend(p,e,HeavenlyRestriction.SCHEMA.get().getRegistryName());h.assertTrue(l!=null,"Loan failed");near(h,gift(e).getMastery(),888,"Mastery lost");h.assertTrue(!gift(e).getOrCreateTag().contains("private_inventory") && !gift(e).getOrCreateTag().contains("schema.build",net.minecraft.nbt.Tag.TAG_COMPOUND) && gift(e).isTemporarySkill(),"Bank state duplicated or ownership became permanent");h.assertTrue(LoanShark.lend(p,e,HeavenlyRestriction.SCHEMA.get().getRegistryName())==null,"Existing skill overwritten");near(h,gift(p).getMastery(),888,"Original removed");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void playersMustAcceptAndForgedRepliesCannotGrant(GameTestHelper h){var p=lender(h);var receiver=actor(h);receiver.setPos(p.position().add(2,0,0));h.assertTrue(LoanShark.lend(p,receiver,HeavenlyRestriction.SCHEMA.get().getRegistryName())==null,"Consent bypass");h.assertTrue(LoanShark.offer(p,receiver,HeavenlyRestriction.SCHEMA.get().getRegistryName()),"Offer failed");UUID nonce=LoanShark.pendingOffer(receiver);h.assertTrue(!LoanShark.reply(p,nonce,true) && !LoanShark.reply(receiver,UUID.randomUUID(),true),"Forged acceptance worked");h.assertTrue(SkillAPI.getSkillsFrom(receiver).getSkill(HeavenlyRestriction.SCHEMA.get()).isEmpty(),"Gift granted before accept");h.assertTrue(LoanShark.reply(receiver,nonce,true),"Accepted gift failed");near(h,gift(receiver).getMastery(),888,"Accepted mastery lost");h.assertTrue(!LoanShark.reply(receiver,nonce,true),"Nonce reused");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void declinedExpiredAndOutOfRangeOffersDoNotGrant(GameTestHelper h){var p=lender(h);var receiver=actor(h);receiver.setPos(p.position().add(2,0,0));h.assertTrue(LoanShark.offer(p,receiver,HeavenlyRestriction.SCHEMA.get().getRegistryName()),"Offer");h.assertTrue(!LoanShark.reply(receiver,LoanShark.pendingOffer(receiver),false),"Decline accepted");h.assertTrue(LoanShark.offer(p,receiver,HeavenlyRestriction.SCHEMA.get().getRegistryName()),"New offer");var d=LoanLedger.get(p.server);d.clock+=601;h.assertTrue(!LoanShark.reply(receiver,LoanShark.pendingOffer(receiver),true),"Expired accepted");h.assertTrue(LoanShark.offer(p,receiver,HeavenlyRestriction.SCHEMA.get().getRegistryName()),"Offer");receiver.setPos(p.position().add(100,0,0));h.assertTrue(!LoanShark.reply(receiver,LoanShark.pendingOffer(receiver),true),"Range check skipped");h.assertTrue(SkillAPI.getSkillsFrom(receiver).getSkill(HeavenlyRestriction.SCHEMA.get()).isEmpty(),"Invalid offer granted");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void activeLoansTransferOneQuarterAndIdleLoansTransferNothing(GameTestHelper h){var p=lender(h);var e=subordinate(h,p);var l=LoanShark.lend(p,e,HeavenlyRestriction.SCHEMA.get().getRegistryName());var a=e.getAttribute(TensuraAttributes.MAX_AURA);double before=a.getBaseValue(),giver=EnergyHelper.getMaxEP(p);a.setBaseValue(before+100);near(h,a.getBaseValue(),before+100,"Idle loan took EP");gift(e).setToggled(true);before=a.getBaseValue();a.setBaseValue(before+100);near(h,a.getBaseValue(),before+75,"Borrower did not keep three quarters");near(h,EnergyHelper.getMaxEP(p)-giver,25,"Gifter did not receive exact quarter");near(h,l.earned,25,"Ledger EP mismatch");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void simultaneousLoansStackWithDiminishingReturnsAcrossLenders(GameTestHelper h){var p=lender(h);var other=lender(h);other.setPos(p.position().add(2,0,0));var e=subordinate(h,p);var first=LoanShark.lend(p,e,HeavenlyRestriction.SCHEMA.get().getRegistryName());TensuraStorages.getExistenceFrom(e).setPermanentOwner(other.getUUID());RestrictionData.learnReward(other,HeavenlyRestriction.PROSPECTOR.get());var second=LoanShark.lend(other,e,HeavenlyRestriction.PROSPECTOR.get().getRegistryName());h.assertTrue(first!=null,"First loan rejected");h.assertTrue(second!=null,"Second loan rejected; source="+SkillAPI.getSkillsFrom(other).getSkill(HeavenlyRestriction.PROSPECTOR.get()).isPresent()+", target="+SkillAPI.getSkillsFrom(e).getSkill(HeavenlyRestriction.PROSPECTOR.get()).isPresent());gift(e).setToggled(true);SkillAPI.getSkillsFrom(e).getSkill(HeavenlyRestriction.PROSPECTOR.get()).orElseThrow().setToggled(true);double ep1=EnergyHelper.getMaxEP(p),ep2=EnergyHelper.getMaxEP(other);var a=e.getAttribute(TensuraAttributes.MAX_MAGICULE);double before=a.getBaseValue();a.setBaseValue(before+100);near(h,a.getBaseValue()-before,56.25,"Two loans did not leave 56.25% of EP");near(h,EnergyHelper.getMaxEP(p)-ep1,21.875,"First lender share");near(h,EnergyHelper.getMaxEP(other)-ep2,21.875,"Second lender share");near(h,first.earned+second.earned,43.75,"Ledger doubled income");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void claimBoundaryStealsOnlyAfterTenMinutesAndRetainsMastery(GameTestHelper h){var p=lender(h);var e=subordinate(h,p);var l=LoanShark.lend(p,e,HeavenlyRestriction.SCHEMA.get().getRegistryName());RestrictionData.learnReward(e,CommonSkills.SELF_REGENERATION.get());var reward=SkillAPI.getSkillsFrom(e).getSkill(CommonSkills.SELF_REGENERATION.get()).orElseThrow();reward.setMastery(333);var d=LoanLedger.get(p.server);d.clock=l.lastUsed+12000;String result=LoanShark.claim(p,l.id);h.assertTrue(result.contains("Claimed"),"Claim failed: "+result);h.assertTrue(SkillAPI.getSkillsFrom(e).getSkill(HeavenlyRestriction.SCHEMA.get()).isEmpty() && SkillAPI.getSkillsFrom(e).getSkill(CommonSkills.SELF_REGENERATION.get()).isEmpty(),"Borrower retained recalled/stolen skills");near(h,SkillAPI.getSkillsFrom(p).getSkill(CommonSkills.SELF_REGENERATION.get()).orElseThrow().getMastery(),333,"Stolen mastery lost");h.assertTrue(LoanShark.claim(p,l.id).contains("closed"),"Repeated claim reused contract");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void activeOrEarlyClaimOnlyRecallsAndCannotTouchIndependentCopies(GameTestHelper h){var p=lender(h);var e=subordinate(h,p);var l=LoanShark.lend(p,e,HeavenlyRestriction.SCHEMA.get().getRegistryName());RestrictionData.learnReward(e,CommonSkills.SELF_REGENERATION.get());var d=LoanLedger.get(p.server);d.clock=l.lastUsed+11999;LoanShark.claim(p,l.id);h.assertTrue(SkillAPI.getSkillsFrom(e).getSkill(CommonSkills.SELF_REGENERATION.get()).isPresent(),"Early claim stole skill");var again=LoanShark.lend(p,e,HeavenlyRestriction.SCHEMA.get().getRegistryName());gift(e).setToggled(true);d.clock=again.lastUsed+13000;LoanShark.claim(p,again.id);h.assertTrue(SkillAPI.getSkillsFrom(e).getSkill(CommonSkills.SELF_REGENERATION.get()).isPresent(),"Active claim stole skill");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void chainedAndEveryUltimateAreExcludedFromTheft(GameTestHelper h){var p=lender(h);var e=subordinate(h,p);var l=LoanShark.lend(p,e,HeavenlyRestriction.SCHEMA.get().getRegistryName());h.assertTrue(RestrictionData.learnReward(e,HeavenlyRestriction.CHAINED.get()),"Chained fixture grant failed");var d=LoanLedger.get(p.server);d.clock=l.lastUsed+12000;LoanShark.claim(p,l.id);h.assertTrue(SkillAPI.getSkillsFrom(e).getSkill(HeavenlyRestriction.CHAINED.get()).isPresent(),"Protected skills stolen");h.assertTrue(SkillAPI.getSkillsFrom(p).getSkill(HeavenlyRestriction.CHAINED.get()).isEmpty(),"Lender received Chained");for(var skillId:SkillAPI.getSkillRegistry().getIds())if(SkillAPI.getSkillRegistry().get(skillId) instanceof io.github.manasmods.tensura.ability.skill.Skill s2 && s2.getType()==io.github.manasmods.tensura.ability.skill.Skill.SkillType.ULTIMATE)h.assertTrue(!LoanShark.claimable(s2.createDefaultInstance()),"Ultimate included in claim pool");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void recordsSurviveSaveLoadAndUsageSeparatesIdleGaps(GameTestHelper h){var p=lender(h);var e=subordinate(h,p);var l=LoanShark.lend(p,e,HeavenlyRestriction.SCHEMA.get().getRegistryName());var d=LoanLedger.get(p.server);d.clock+=200;gift(e).setToggled(true);LoanShark.sample(d,l,e);d.clock++;LoanShark.sample(d,l,e);gift(e).setToggled(false);d.clock+=120;LoanShark.sample(d,l,e);d.clock+=100;gift(e).setToggled(true);LoanShark.sample(d,l,e);near(h,l.used,3,"Use duration included idle time");h.assertTrue(l.lastGap>=220 && l.longestGap>=220,"Idle gap not tracked");var tag=d.save(new net.minecraft.nbt.CompoundTag(),p.registryAccess());var restored=LoanLedger.load(tag,p.registryAccess());var copy=restored.loans.get(l.id);h.assertTrue(copy!=null && copy.borrower.equals(e.getUUID()) && copy.used==l.used && copy.lastUsed==l.lastUsed && copy.wasActive==l.wasActive,"Record lost on save/load");h.assertTrue(ChainedReincarnation.blocked(HeavenlyRestriction.LOAN_SHARK.get(),p),"Skill-taking reincarnation blacklist missing");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void nativeKillEpAndExponentiationTransferOnlyOnce(GameTestHelper h){var p=lender(h);var e=subordinate(h,p);var victim=target(h,e.position().add(3,0,0));var l=LoanShark.lend(p,e,HeavenlyRestriction.SCHEMA.get().getRegistryName());RestrictionData.learnReward(e,HeavenlyRestriction.EXPONENTIATION.get());RestrictionData.learnReward(p,HeavenlyRestriction.EXPONENTIATION.get());TensuraStorages.getAbilityFrom(e).setAbilitySlot(0,0,HeavenlyRestriction.EXPONENTIATION.get(),0);TensuraStorages.getAbilityFrom(p).setAbilitySlot(0,0,HeavenlyRestriction.EXPONENTIATION.get(),0);var a=e.getAttribute(TensuraAttributes.MAX_AURA);var m=e.getAttribute(TensuraAttributes.MAX_MAGICULE);double ab=a.getBaseValue(),mb=m.getBaseValue(),before=EnergyHelper.getMaxEP(e);io.github.manasmods.tensura.handler.DeathHandler.gainEPEntity(e,victim,9);double gain=EnergyHelper.getMaxEP(e)-before;a.setBaseValue(ab);m.setBaseValue(mb);gift(e).setToggled(true);double lenderBefore=EnergyHelper.getMaxEP(p);io.github.manasmods.tensura.handler.DeathHandler.gainEPEntity(e,victim,9);near(h,EnergyHelper.getMaxEP(e)-before,gain*.75,"Native EP was not shared after Exponentiation");near(h,EnergyHelper.getMaxEP(p)-lenderBefore,gain*.25,"Transferred EP was squared or taxed twice");near(h,l.earned,gain*.25,"Native award report mismatch");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void pendingCreditPersistsPaysOnceAndForeignClaimsFail(GameTestHelper h){var p=lender(h);var e=subordinate(h,p);var l=LoanShark.lend(p,e,HeavenlyRestriction.SCHEMA.get().getRegistryName());var other=lender(h);h.assertTrue(LoanShark.claim(other,l.id).contains("not yours"),"Foreign contract accepted");var d=LoanLedger.get(p.server);d.pending.put(p.getUUID(),50d);var restored=LoanLedger.load(d.save(new net.minecraft.nbt.CompoundTag(),p.registryAccess()),p.registryAccess());near(h,restored.pending.get(p.getUUID()),50,"Offline credit lost on reload");double before=EnergyHelper.getMaxEP(p);LoanShark.pay(restored,p);LoanShark.pay(restored,p);near(h,EnergyHelper.getMaxEP(p)-before,50,"Credit was lost or paid twice");h.succeed();}

    @GameTest(template="empty",timeoutTicks=100)
    public static void fusedBorrowedSkillsKeepTheirContractAndRecallFromBothBodies(GameTestHelper h){var p=lender(h);var host=subordinate(h,p);var l=LoanShark.lend(p,host,HeavenlyRestriction.SCHEMA.get().getRegistryName());var controller=actor(h);controller.setPos(p.position().add(2,0,0));RestrictionData.learnReward(controller,HeavenlyRestriction.FUSION.get());TensuraStorages.getExistenceFrom(host).setPermanentOwner(controller.getUUID());afterTracking(h,List.of(host),()->{h.assertTrue(dev.heavenlyrestriction.fusion.Fusion.fuseSubordinate(controller,host),"Fusion failed");try{gift(controller).setToggled(true);var a=controller.getAttribute(TensuraAttributes.MAX_AURA);double before=a.getBaseValue(),income=EnergyHelper.getMaxEP(p);a.setBaseValue(before+100);near(h,a.getBaseValue()-before,75,"Fusion bypassed borrower fee");near(h,EnergyHelper.getMaxEP(p)-income,25,"Fusion contract credit missing");LoanShark.claim(p,l.id);h.assertTrue(SkillAPI.getSkillsFrom(host).getSkill(HeavenlyRestriction.SCHEMA.get()).isEmpty() && SkillAPI.getSkillsFrom(controller).getSkill(HeavenlyRestriction.SCHEMA.get()).isEmpty(),"Fusion kept a recalled copy");}finally{dev.heavenlyrestriction.fusion.Fusion.end(controller,"Test");}h.succeed();});}

    @GameTest(template="empty",timeoutTicks=100)
    public static void ongoingFlightCountsAndDisabledTogglesDoNot(GameTestHelper h){var p=lender(h);var receiver=actor(h);receiver.setPos(p.position().add(2,0,0));h.assertTrue(RestrictionData.learnReward(p,HeavenlyRestriction.AIR_SOVEREIGNTY.get()),"Air Walk source grant");h.assertTrue(LoanShark.offer(p,receiver,HeavenlyRestriction.AIR_SOVEREIGNTY.get().getRegistryName()),"Air Walk offer");h.assertTrue(LoanShark.reply(receiver,LoanShark.pendingOffer(receiver),true),"Air Walk accept");var i=SkillAPI.getSkillsFrom(receiver).getSkill(HeavenlyRestriction.AIR_SOVEREIGNTY.get()).orElseThrow();var d=LoanLedger.get(p.server);var flight=d.loans.get(i.getTag().getUUID(LoanShark.TOKEN));i.onPressed(receiver,0,0);d.clock+=200;h.assertTrue(LoanShark.active(d,flight,receiver),"Ongoing flight stopped counting after cast window");receiver.getAbilities().flying=false;h.assertTrue(!LoanShark.active(d,flight,receiver),"Landed flight counted as active");AirSovereigntyArt.stop(receiver);RestrictionData.learnReward(p,HeavenlyRestriction.PROSPECTOR.get());h.assertTrue(LoanShark.offer(p,receiver,HeavenlyRestriction.PROSPECTOR.get().getRegistryName()),"Toggle offer");h.assertTrue(LoanShark.reply(receiver,LoanShark.pendingOffer(receiver),true),"Toggle accept");var toggle=SkillAPI.getSkillsFrom(receiver).getSkill(HeavenlyRestriction.PROSPECTOR.get()).orElseThrow();var loan=d.loans.get(toggle.getTag().getUUID(LoanShark.TOKEN));toggle.setToggled(false);TensuraStorages.getAbilityFrom(receiver).setAbilitySlot(0,0,toggle.getSkill(),0);h.assertTrue(!LoanShark.active(d,loan,receiver),"Disabled toggle counted as use merely because equipped");h.succeed();}

    @GameTest(template="empty",timeoutTicks=100)
    public static void cappedCreditDoesNotMintHiddenEpAndCrossingCapsKeepsThreeQuarters(GameTestHelper h){var p=lender(h);var e=subordinate(h,p);var l=LoanShark.lend(p,e,HeavenlyRestriction.SCHEMA.get().getRegistryName());var pa=p.getAttribute(TensuraAttributes.MAX_AURA);var pm=p.getAttribute(TensuraAttributes.MAX_MAGICULE);double limit=((net.minecraft.world.entity.ai.attributes.RangedAttribute)pa.getAttribute().value()).getMaxValue();pa.setBaseValue(limit);pm.setBaseValue(limit);var d=LoanLedger.get(p.server);d.pending.put(p.getUUID(),50d);LoanShark.pay(d,p);LoanShark.pay(d,p);near(h,pa.getBaseValue(),limit,"Full pool accumulated hidden repeated credits");near(h,pm.getBaseValue(),limit,"Full magicule pool accumulated hidden credits");near(h,d.pending.get(p.getUUID()),50,"Capped credit disappeared");var a=e.getAttribute(TensuraAttributes.MAX_AURA);a.setBaseValue(limit-10);gift(e).setToggled(true);a.setBaseValue(limit+100);near(h,a.getValue(),limit-2.5,"Near-cap award did not keep three quarters of actual gain");near(h,l.earned,2.5,"Near-cap award transferred wrong amount");h.succeed();}

    @GameTest(template="empty",timeoutTicks=100)
    public static void threeGiftsDiminishAndOnlyActiveGiftsStackPerBorrower(GameTestHelper h){
        var p=lender(h);var e=subordinate(h,p);
        var schema=LoanShark.lend(p,e,HeavenlyRestriction.SCHEMA.get().getRegistryName());
        RestrictionData.learnReward(p,HeavenlyRestriction.PROSPECTOR.get());
        var prospector=LoanShark.lend(p,e,HeavenlyRestriction.PROSPECTOR.get().getRegistryName());
        var recovery=HeavenlyRestriction.REGENERATION.getFirst().get();
        h.assertTrue(RestrictionData.learnReward(p,recovery),"Recovery source grant failed");var third=LoanShark.lend(p,e,recovery.getRegistryName());
        h.assertTrue(schema!=null,"Schema gift failed");h.assertTrue(prospector!=null,"Prospector gift failed");h.assertTrue(third!=null,"Recovery gift failed");
        SkillAPI.getSkillsFrom(e).getSkill(recovery).orElseThrow().setToggled(true);
        gift(e).setToggled(true);var mining=SkillAPI.getSkillsFrom(e).getSkill(HeavenlyRestriction.PROSPECTOR.get()).orElseThrow();mining.setToggled(true);
        var a=e.getAttribute(TensuraAttributes.MAX_AURA);double before=a.getValue(),income=EnergyHelper.getMaxEP(p);a.setBaseValue(a.getBaseValue()+160);
        near(h,a.getValue()-before,67.5,"Three active gifts should leave 42.1875% of EP");near(h,EnergyHelper.getMaxEP(p)-income,92.5,"Three gifts should transfer 57.8125%");
        near(h,schema.earned+prospector.earned+third.earned,92.5,"Stacked ledger lost or duplicated EP");near(h,schema.earned,third.earned,"Gift order changed entitlement");
        gift(e).setToggled(false);before=a.getValue();income=EnergyHelper.getMaxEP(p);a.setBaseValue(a.getBaseValue()+160);
        near(h,a.getValue()-before,90,"Idle gift counted toward two-gift rate");near(h,EnergyHelper.getMaxEP(p)-income,70,"Two active gifts should transfer 43.75%");
        mining.setToggled(false);before=a.getValue();income=EnergyHelper.getMaxEP(p);a.setBaseValue(a.getBaseValue()+160);
        near(h,a.getValue()-before,120,"Only recovery should remain active");near(h,EnergyHelper.getMaxEP(p)-income,40,"One active gift should transfer 25%");
        var other=subordinate(h,p);var separate=LoanShark.lend(p,other,HeavenlyRestriction.SCHEMA.get().getRegistryName());h.assertTrue(separate!=null,"Separate borrower gift failed");gift(other).setToggled(true);
        var otherAura=other.getAttribute(TensuraAttributes.MAX_AURA);before=otherAura.getValue();otherAura.setBaseValue(otherAura.getBaseValue()+160);near(h,otherAura.getValue()-before,120,"Another borrower's gifts increased the rate");
        LoanShark.claim(p,third.id);before=a.getValue();income=EnergyHelper.getMaxEP(p);a.setBaseValue(a.getBaseValue()+160);
        near(h,a.getValue()-before,160,"Recalled or idle gifts still taxed EP");near(h,EnergyHelper.getMaxEP(p)-income,0,"Inactive lender still received EP");h.succeed();
    }

}
